def finalize_lessons():
    """Resolve stable authoring keys to immutable lesson identifiers."""
    key_to_id = {lesson["key"]: f"L{i:03d}" for i, lesson in enumerate(lessons)}
    finalized = []
    for lesson in lessons:
        out = {
            "lesson_id": key_to_id[lesson["key"]],
            "curriculum_key": lesson["key"],
            "phase": lesson["phase"],
            "topic": lesson["topic"],
            "point": lesson["point"],
            "world_objective": lesson["world_objective"],
            "principal_novelty": lesson["principal_novelty"],
            "frontier_language": lesson["frontier_language"],
            "required_established_language": lesson["required_established_language"],
            "foundation_grounding_dependencies": lesson["foundation_grounding_dependencies"],
            "prerequisite_lessons": [key_to_id[k] for k in lesson["prerequisite_keys"]],
            "grounding_modes": lesson["grounding_modes"],
            "picture_book": lesson["picture_book"],
            "characters": lesson["characters"],
            "locations": lesson["locations"],
            "chronology_constraints": lesson["chronology"],
            "interference_set": lesson["interference_set"],
            "evaluation_targets": lesson["evaluation_targets"],
            "source_provenance": lesson["source_provenance"],
            "intended_later_rehearsal_targets": [],
            "identity_scope": lesson["identity_scope"],
            "compiler_notes": lesson["compiler_notes"],
        }
        finalized.append(out)
    return finalized, key_to_id


