def build_rehearsal_layer(acquisitions, rehearsals, gates):
    coverage = Counter()
    for row in rehearsals:
        for aid in row["cold_retrieval_targets"]:
            coverage[aid] += 1
    return {
        "schema_version": "6.0",
        "title": "Ninereeds v6 scheduled rehearsal and transfer layer",
        "status": "complete_pending_independent_adversarial_review",
        "metadata": {
            "acquisition_lesson_count": len(acquisitions),
            "scheduled_rehearsal_count": len(rehearsals),
            "planned_conducted_total": len(acquisitions) + len(rehearsals),
            "conditional_gate_count": len(gates),
            "conditional_lessons_in_total": 0,
            "minimum_cold_retrievals_per_acquisition": min(coverage.values()),
            "maximum_cold_retrievals_per_acquisition": max(coverage.values()),
            "coverage_record_count": len(coverage),
            "schedule_position": "Begins after the complete acquisition sequence; R001 follows the final L lesson.",
            "novelty_policy": "All frontier_language and new_world_facts arrays must be empty.",
            "spacing_strategy": (
                "Two ordered coverage passes place a second retrieval roughly half the scheduled layer after "
                "the first; forty curated recombination templates recur about every 40 rehearsals with rotating TOPICs."
            ),
        },
        "scheduled_rehearsals": rehearsals,
        "conditional_diagnostic_remedial_gates": gates,
    }


def readme_text(curriculum, source_accounting, rehearsal_layer, validation):
    status = validation.get("status", "UNKNOWN")
    return f"""# Ninereeds curriculum v6 — independent Sol synthesis

Status: **{curriculum['status']}**. Structural self-validation: **{status}**. Independent adversarial pedagogical review has not been performed and is intentionally out of scope for this synthesis.

## Counts

- Acquisition lessons: **{curriculum['metadata']['acquisition_lesson_count']}** (`L000`–`{curriculum['metadata']['last_lesson_id']}`)
- Scheduled rehearsal/transfer lessons: **{rehearsal_layer['metadata']['scheduled_rehearsal_count']}** (`R001`–`R{rehearsal_layer['metadata']['scheduled_rehearsal_count']:03d}`)
- Planned conducted total: **{rehearsal_layer['metadata']['planned_conducted_total']}**
- Conditional diagnostic/remedial gates: **{rehearsal_layer['metadata']['conditional_gate_count']}**, not counted unless triggered
- Required picture books: **{curriculum['metadata']['picture_book_counts']['required']}**; optional: **{curriculum['metadata']['picture_book_counts']['optional']}**; no-book: **{curriculum['metadata']['picture_book_counts']['no']}**
- C001–C240 accounting records: **{source_accounting['record_count']}** ({source_accounting['disposition_counts'].get('active', 0)} active; {source_accounting['disposition_counts'].get('consolidated', 0)} consolidated; {source_accounting['disposition_counts'].get('deferred', 0)} deferred; {source_accounting['disposition_counts'].get('excluded', 0)} excluded)

The {curriculum['metadata']['acquisition_lesson_count']} acquisition count is intentional. Actual novelty counting, restored foundational language, comprehensive world coverage, and separation of acquisition from transfer make a 300-lesson cap pedagogically dishonest. The combined total is {rehearsal_layer['metadata']['planned_conducted_total']}, within the requested 600–700 planning range.

## Artifact map

| File | Role |
|---|---|
| `README.md` | Status, counts, artifact map, and unresolved decisions |
| `synthesis_decisions.md` | V4/v5 comparison, accepted/rejected/transformed decisions, architecture, and granularity rationale |
| `curriculum_v6.json` | Normative {curriculum['metadata']['acquisition_lesson_count']}-lesson acquisition skeleton with dependencies, surface closure, grounding, chronology, evaluation, provenance, and rehearsal links |
| `curriculum_v6.md` | Readable complete acquisition sequence |
| `source_accounting_v6.json` | Exactly one evidence-based disposition record for each C001–C240 |
| `rehearsal_layer_v6.json` | Normative 270-entry no-novelty schedule plus separate conditional gates |
| `rehearsal_layer_v6.md` | Readable schedule and spacing/transfer explanation |
| `asset_policy_v6.md` | V4/v5 visual comparison, required-book inventory, variation, references, crops, and fallback policy |
| `validate_curriculum_v6.py` | Read-only structural validator; it does not score pedagogy |
| `self_validation_v6.json` | Actual captured validator result |
| `build_v6.py` | Deterministic atomic artifact authoring helper retained for auditability; not a lesson compiler or training entry point |

## Binding unresolved decisions

{os.linesep.join(f"- **{row['id']}**: {row['decision']} {row['constraint']}" for row in curriculum['unresolved_decisions'])}

## Boundaries

No source proposal, world file, policy, mission file, training data, service, or image registry was modified. No model training, image acquisition, download, generation, or live Campaign 36 action was started. The visual foundation is treated as reviewed referential grounding, not as fluent language or a complete world model.
"""


def build_all():
    acquisitions, key_to_id = finalize_lessons()
    rehearsals = build_rehearsals(acquisitions, key_to_id)
    gates = diagnostic_gates(acquisitions)

    # Materialize actual later-rehearsal links into the acquisition records.
    acquisition_by_id = {lesson["lesson_id"]: lesson for lesson in acquisitions}
    for row in rehearsals:
        for aid in row["prerequisite_acquisition_lessons"]:
            acquisition_by_id[aid]["intended_later_rehearsal_targets"].append(row["rehearsal_id"])
    for lesson in acquisitions:
        lesson["intended_later_rehearsal_targets"] = uniq(lesson["intended_later_rehearsal_targets"])
        if len(lesson["intended_later_rehearsal_targets"]) < 2:
            raise AssertionError(f"{lesson['lesson_id']} lacks two later rehearsal targets")

    source_accounting = build_source_accounting(acquisitions)
    curriculum = build_curriculum_object(acquisitions, source_accounting)
    rehearsal_layer = build_rehearsal_layer(acquisitions, rehearsals, gates)

    atomic_json(OUT / "curriculum_v6.json", curriculum)
    atomic_text(OUT / "curriculum_v6.md", curriculum_markdown(curriculum))
    atomic_json(OUT / "source_accounting_v6.json", source_accounting)
    atomic_json(OUT / "rehearsal_layer_v6.json", rehearsal_layer)
    atomic_text(OUT / "rehearsal_layer_v6.md", rehearsal_markdown(rehearsal_layer))
    atomic_text(OUT / "synthesis_decisions.md", synthesis_markdown(curriculum, source_accounting, rehearsal_layer))
    atomic_text(OUT / "asset_policy_v6.md", asset_policy_markdown(curriculum))

    validator = OUT / "validate_curriculum_v6.py"
    if not validator.exists():
        raise FileNotFoundError("write validate_curriculum_v6.py before running the builder")
    proc = subprocess.run(
        [sys.executable, str(validator), "--json"],
        cwd=OUT,
        check=False,
        text=True,
        capture_output=True,
    )
    try:
        validation = json.loads(proc.stdout)
    except json.JSONDecodeError:
        validation = {
            "status": "FAIL",
            "errors": ["Validator did not emit JSON", proc.stdout, proc.stderr],
            "warnings": [],
        }
    validation["command"] = "python3 validate_curriculum_v6.py --json"
    validation["exit_code"] = proc.returncode
    validation["captured_for"] = "self_validation_v6.json"
    atomic_json(OUT / "self_validation_v6.json", validation)
    atomic_text(OUT / "README.md", readme_text(curriculum, source_accounting, rehearsal_layer, validation))
    if proc.returncode != 0 or validation.get("status") != "PASS":
        raise SystemExit("Structural validation failed; inspect self_validation_v6.json")


if __name__ == "__main__":
    build_all()
